3	import { supabase } from "@/integrations/supabase/client";
4	import { useAuth } from "@/hooks/useAuth";
5	
6	export type NoteType = "general" | "positive" | "concern" | "flag";
7	
8	export interface CandidateNote {
9	  id: string;
10	  resume_id: string;
11	  job_id: string;
12	  author_id: string;
13	  note_type: NoteType;
14	  content: string;
15	  created_at: string;
16	  updated_at: string;
17	}
18	
19	export function useCandidateNotes(resumeId: string | null, jobId: string | null) {
20	  const { user } = useAuth();
21	  const queryClient = useQueryClient();
22	  const queryKey = ["candidate-notes", resumeId, jobId];
23	
24	  const { data: notes = [], isLoading } = useQuery<CandidateNote[]>({
25	    queryKey,
26	    queryFn: async () => {
27	      if (!resumeId || !jobId) return [];
28	      const { data, error } = await (supabase as any)
29	        .from("candidate_notes")
30	        .select("*")
31	        .eq("resume_id", resumeId)
32	        .eq("job_id", jobId)
33	        .order("created_at", { ascending: false });
34	      if (error) throw error;
35	      return data ?? [];
36	    },
37	    enabled: !!resumeId && !!jobId,
38	    staleTime: 30_000,
39	  });
40	
41	  useEffect(() => {
42	    if (!resumeId || !jobId) return;
43	    const channel = supabase
44	      .channel(`notes-${resumeId}-${jobId}`)
45	      .on("postgres_changes", {
46	        event: "*",
47	        schema: "public",
48	        table: "candidate_notes",
49	        filter: `resume_id=eq.${resumeId}`,
50	      }, () => {
51	        queryClient.invalidateQueries({ queryKey });
52	      })
53	      .subscribe();
54	    return () => { supabase.removeChannel(channel); };
55	  }, [resumeId, jobId, queryClient]);
56	
57	  const addNote = useMutation({
58	    mutationFn: async ({ content, noteType }: { content: string; noteType: NoteType }) => {
59	      const { error } = await (supabase as any)
60	        .from("candidate_notes")
61	        .insert({ resume_id: resumeId, job_id: jobId, author_id: user?.id, note_type: noteType, content });
62	      if (error) throw error;
63	    },
64	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
65	  });
66	
67	  const deleteNote = useMutation({
68	    mutationFn: async (noteId: string) => {
69	      const { error } = await (supabase as any)
70	        .from("candidate_notes")
71	        .delete()
72	        .eq("id", noteId);
73	      if (error) throw error;
74	    },
75	    onSuccess: () => queryClient.invalidateQueries({ queryKey }),
76	  });
77	
78	  return { notes, isLoading, addNote, deleteNote, currentUserId: user?.id };
79	}
